CELL = [(r, i) for r in range(4) for i in range(4 - r)]
FRONT = {c: tuple((c[0] + 1, j) for j in (c[1] - 1, c[1]) if 0 <= j < 3 - c[0]) for c in CELL}
BACK = {c: tuple((c[0] - 1, j) for j in (c[1], c[1] + 1) if c[0] and 0 <= j < 5 - c[0]) for c in CELL}
NB = {c: tuple(x for x in CELL if x != c and (x in FRONT[c] or x in BACK[c] or
      (x[0] == c[0] and abs(x[1] - c[1]) == 1))) for c in CELL}


def gh(S):
    """The rule: pins that fell although every pin in front of them still stands."""
    return sum(1 for c in S if FRONT[c] and all(x not in S for x in FRONT[c]))


def rivals(F):
    """Rival counts. hard: the three neighbours of the rule + anything the clue
    already gives away. soft: other picture statistics a player may tally."""
    E = B = I = C = D = K = W = J = A = 0
    for S in F:
        for c in CELL:
            f, b, m = FRONT[c], BACK[c], NB[c]
            if c in S:
                E += bool(f) and any(x not in S for x in f)
                B += bool(b) and all(x not in S for x in b)
                I += not any(x in S for x in m)
                K += c[0] == 0
                W += c[0] == 3
            else:
                C += bool(f) and all(x in S for x in f)
                D += bool(b) and all(x in S for x in b)
                A += not any(x not in S for x in m)
        J += sum(1 for r in range(4) if all((r, i) in S for i in range(4 - r)))
    t = sum(len(S) for S in F)
    g = [gh(S) for S in F]
    return ((E, B, C), (I, D, K, W, J, A, t, len(F), 10 * len(F) - t,
            sum(1 for x in g if x), sum(1 for x in g if not x)))


def draw(dig, F):
    out = ["  ".join(str(x).center(4) for x in dig)]
    for r in range(4):
        out.append("  ".join(" " * r + "".join("." if (r, i) in S else "o"
                                               for i in range(4 - r)) for S in F))
    return "\n".join(x.rstrip() for x in out)


def pool(d):
    P = {}
    for S in itertools.combinations(CELL, d):
        P.setdefault(gh(set(S)), []).append(set(S))
    return P


def split(dig, n, P, r):
    for _ in range(300):
        g, rem = [], n
        for k, x in enumerate(dig):
            left = sum(max(P[y]) for y in dig[k + 1:])
            ch = [v for v in P[x] if 0 <= rem - v <= left]
            if not ch:
                break
            v = r.choice(ch)
            g.append(v)
            rem -= v
        else:
            if rem == 0:
                return g
    return None


def quality(F, n, grade):
    """grade 0 = every demo guarantee, 1 = weaker, 2 = the rival test only."""
    H, Sf = rivals(F)
    if n:
        if n in H or sum(v == n for v in Sf) > 1:
            return False
    if not all(H):
        return False
    two = near = deep = row2 = 0
    for S in F:
        for c in S:
            f = FRONT[c]
            if f:
                st = [x for x in f if x not in S]
                two += len(st) == len(f) == 2
                near += 0 < len(st) < len(f)
                deep += not st
                row2 += len(st) == len(f) and c[0] == 2
    heads = sum(1 for S in F if (3, 0) in S)
    ok = near and deep and (not n or 0 < heads < len(F))
    if grade > 1:
        return True
    if grade:
        return ok
    per = [gh(S) for S in F]
    return bool(ok and (not n or (two and len(set(per)) > 1 and not min(per)
                and (n < 2 or row2) and (n < 3 or max(per) > 1))))


def solve(clue):
    a, b = clue.split("/")
    dig = [int(x) for x in a]
    n = int(b)
    r = random.Random(clue)
    P = {d: pool(d) for d in set(dig)}
    best = None
    for grade in (0, 1, 2):
        for _ in range(160 if grade < 2 else 400):
            g = split(dig, n, P, r)
            if g is None:
                return draw(dig, best) if best else ""
            F = [r.choice(P[dig[k]][v]) for k, v in enumerate(g)]
            if quality(F, n, grade):
                return draw(dig, F)
            best = F
    return draw(dig, best) if best else ""

